python3 -c "
import json, os, sys
d = json.load(sys.stdin)
agent = d.get('agent_type') or 'sesión principal'
path = os.path.abspath((d.get('tool_input') or {}).get('file_path') or '.')
for root in (d.get('cwd'), os.environ.get('CLAUDE_PROJECT_DIR')):
    if not root:
        continue
    try:
        rel = os.path.relpath(path, root).replace(os.sep, '/')
        top = rel.split('/')[0]
    except ValueError:
        continue
    if rel == '.claude/state' or rel.startswith('.claude/state/'):
        print('[harness] Bloqueado: .claude/state/ lo escriben solo los hooks del harness.', file=sys.stderr)
        sys.exit(2)
    if top in ('src', 'tests') and agent != 'implementer':
        print('[harness] Bloqueado: solo el subagente implementer escribe en src/ y tests/ (agente actual: ' + agent + '). Delega el cambio con la herramienta Agent.', file=sys.stderr)
        sys.exit(2)
"

python3 -c "import json, os, sys
try:
    d = json.load(sys.stdin)
    if (d.get('tool_input') or {}).get('subagent_type') != 'reviewer':
        sys.exit(0)
    roots = [r for r in (os.environ.get('CLAUDE_PROJECT_DIR'), d.get('cwd')) if r and os.path.isfile(os.path.join(r, 'feature_list.json'))]
    if not roots:
        sys.exit(0)
    root = roots[0]
    feats = json.load(open(os.path.join(root, 'feature_list.json'), encoding='utf-8')).get('features') or []
    cur = [f.get('name') for f in feats if isinstance(f, dict) and f.get('status') == 'in_progress']
    if len(cur) != 1 or not cur[0]:
        sys.exit(0)
    name = cur[0]
    path = os.path.join(root, '.claude', 'state', 'review_rounds.json')
    try:
        state = json.load(open(path, encoding='utf-8'))
        if not isinstance(state, dict):
            state = {}
    except Exception:
        state = {}
    n = int(state.get(name, 0))
except Exception:
    sys.exit(0)
if n >= 3:
    print('[harness] Límite de 3 rondas de revisión alcanzado para la feature ' + name + '. No lances otro reviewer: para y explica al humano qué hallazgos siguen abiertos, por qué no convergen y qué opciones ves. El contador se reinicia cuando el humano responde.', file=sys.stderr)
    sys.exit(2)
try:
    state[name] = n + 1
    os.makedirs(os.path.dirname(path), exist_ok=True)
    json.dump(state, open(path, 'w', encoding='utf-8'), ensure_ascii=False)
except Exception:
    pass
sys.exit(0)"

python3 -c "
import json, os, subprocess, sys
d = json.load(sys.stdin)
path = os.path.abspath((d.get('tool_input') or {}).get('file_path') or '.')
for root in (d.get('cwd'), os.environ.get('CLAUDE_PROJECT_DIR')):
    if not root:
        continue
    try:
        rel = os.path.relpath(path, root).replace(os.sep, '/')
    except ValueError:
        continue
    if rel.split('/')[0] in ('src', 'tests'):
        run = subprocess.run([sys.executable, '-m', 'unittest', 'discover', '-s', 'tests', '-q'], cwd=root, capture_output=True, text=True)
        if run.returncode:
            print('[harness] Tests en rojo tras editar ' + rel + ':', file=sys.stderr)
            print(chr(10).join((run.stdout + run.stderr).strip().splitlines()[-15:]), file=sys.stderr)
            sys.exit(2)
        break
"

