python3 -c "import json, os, re, subprocess, sys
try:
    d = json.load(sys.stdin)
except Exception:
    d = {}
roots = [r for r in (os.environ.get('CLAUDE_PROJECT_DIR'), d.get('cwd')) if r and os.path.isfile(os.path.join(r, 'init.sh'))]
if not roots:
    sys.exit(0)
try:
    run = subprocess.run(['bash', 'init.sh', '--status'], cwd=roots[0], capture_output=True, text=True, timeout=40)
except Exception as e:
    print('[harness] No se pudo generar el estado del proyecto: ' + str(e))
    sys.exit(0)
lines = re.sub(chr(27) + r'\\[[0-9;]*m', '', run.stdout).splitlines()
start = next((i for i, l in enumerate(lines) if 'Estado del trabajo' in l), len(lines))
problems = [l for l in lines[:start] if '[FAIL]' in l or '[WARN]' in l]
print('== Estado real del proyecto (generado por ./init.sh --status al iniciar la sesión) ==')
print('Manda sobre cualquier estado escrito a mano en progress/. No incluye análisis estático, tests ni grafo: para eso ejecuta ./init.sh.')
print(chr(10).join(l for l in problems + lines[start:] if l.strip()))
sys.exit(0)"
